gion']??'')?>"></div><div class="form-field"><label>Postal code</label><input name="postal_code" value="<?=e($r['postal_code']??'')?>"></div><div class="form-field"><label>Country</label><input name="country" value="<?=e($r['country']??'')?>"></div></div><h2>Sales and credit</h2><div class="finance-filter-form"><div class="form-field"><label>Salesperson</label><select name="agent_id"><option value="">Unassigned</option><?php foreach($data['agents'] as $a):?><option value="<?=e($a['agent_id'])?>" <?=(int)$r['agent_id']===(int)$a['agent_id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Sales team</label><select name="team_id"><option value="">Unassigned</option><?php foreach($data['salesTeams'] as $t):?><option value="<?=e($t['team_id'])?>" <?=(int)$r['team_id']===(int)$t['team_id']?'selected':''?>><?=e($t['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Pricelist</label><select name="pricelist_id"><option value="">Standard</option><?php foreach($data['pricelists'] as $p):?><option value="<?=e($p['pricelist_id'])?>" <?=(int)$r['pricelist_id']===(int)$p['pricelist_id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Territory</label><select name="territory_id"><option value="">Unassigned</option><?php foreach($data['territories'] as $t):?><option value="<?=e($t['territory_id'])?>" <?=(int)$r['territory_id']===(int)$t['territory_id']?'selected':''?>><?=e($t['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Payment terms (days)</label><input type="number" min="0" name="payment_terms_days" value="<?=e($r['payment_terms_days'])?>"></div><div class="form-field"><label>Currency</label><input name="preferred_currency" maxlength="3" value="<?=e($r['preferred_currency'])?>"></div><div class="form-field"><label>Credit policy</label><select name="credit_mode"><?php foreach(['no_credit','fixed','unlimited'] as $v):?><option value="<?=e($v)?>" <?=$r['credit_mode']===$v?'selected':''?>><?=e(str_replace('_',' ',$v))?></option><?php endforeach;?></select></div><div class="form-field"><label>Credit limit</label><input type="number" min="0" step="0.01" name="credit_limit" value="<?=e($r['credit_limit'])?>"></div><div class="form-field"><label>Credit status</label><select name="credit_status"><?php foreach(['active','hold','blocked'] as $v):?><option value="<?=e($v)?>" <?=$r['credit_status']===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div></div><?php if($can):?><button class="btn btn-primary">Save customer</button><?php endif;?></form><?php if($can):?><form method="post" action="/office_app/public/sales/customers/<?=e($r['customer_id'])?>/active"><?=csrfField()?><input type="hidden" name="active" value="<?=!empty($r['active'])?'0':'1'?>"><button class="btn btn-secondary"><?=!empty($r['active'])?'Archive':'Activate'?></button></form><?php endif;?>
